import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Use a plane that matches the aspect ratio of the provided atlas region (512x320)
  const aspect = 512 / 320;
  const width = 1.6 * aspect; // arbitrary base unit scaled to keep reasonable size
  const height = 1.6;
  const geometry = new PlaneGeometry(width, height);

  // Basic material; will receive texture asynchronously
  const material = new MeshBasicNodeMaterial();
  material.color = 0xffffff; // ensure texture colors are visible

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture (imageUrl) and assign when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Event handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Keep track of any GSAP timelines (none for this static node)
  const timelines = [];

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Dispose material and geometry
    if (material) material.dispose();
    if (geometry) geometry.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
  };

  return root;
}
